rules:
// Sterownik VAV Nefryt. p = odczyt biezacy, prev = poprzedni.
// Wymiary kanalow w METRACH. Kanal nieuzywany ma wymiary 0 i nie wnosi nic do sumy.
const jest=k=>typeof p[k]==='number'&&isFinite(p[k]);
const tol=(a,b,proc,abs)=>Math.abs(a-b)<=Math.abs(a)*proc/100+(abs||1);

// Kanaly danej strony: obsluguje i wariant per kanal (Supply1/Supply2),
// i stary wariant z jedna para wymiarow (Supply).
function kanaly(strona, zrodlo){
 const out=[];
 for(const i of ['1','2','']){
  const H=strona+i+'H', V=strona+i+'V', v='Speed'+strona+i, k='K'+strona+i;
  if(jest(H)&&jest(V)&&jest(v)&&p[H]*p[V]>0)
   out.push({A:p[H]*p[V], v:(zrodlo||p)[v], k:jest(k)?p[k]:1});
 }
 return out;
}
const przeplyw=ks=>ks.reduce((s,c)=>s+c.k*c.v*c.A*3600,0);
const S=kanaly('Supply'), R=kanaly('Return');

// Przeplyw policzony poprawnie: suma v_i * A_i (kazdy kanal ze swoim przekrojem)
const q_sup_calc=przeplyw(S), q_ext_calc=przeplyw(R);
// Przeplyw z urzadzenia; gdy brak punktu - spadamy na wartosc policzona
const q_sup=jest('FlowSupply')?p.FlowSupply:q_sup_calc;
const q_ext=jest('FlowReturn')?p.FlowReturn:q_ext_calc;

// Rampa CO2 i tryb
const x1=p.CO2Setpoint-p.CO2PropBand;
const ramp=Math.min(1,Math.max(0,(p.CO2-x1)/(p.CO2PropBand||1)));
const sp_auto=p.MinFlow+ramp*(p.MaxFlow-p.MinFlow);
const m=Number(p.Mode);
const sp_sup=m===1?sp_auto:m===2?p.MinFlow:m===3?p.MaxFlow:0;
const sp_ext=sp_sup-p.Diff;

// Regulacje oceniamy dopiero po ustabilizowaniu; przeplyw poprzedni liczymy
// tak samo jak biezacy, inaczej przy braku FlowSupply porownywalibysmy go ze soba.
const stoi=(a,b)=>tol(a,b,1,5);
const q_sup_prev=jest('FlowSupply')?prev.FlowSupply:przeplyw(kanaly('Supply',prev));
const q_ext_prev=jest('FlowReturn')?prev.FlowReturn:przeplyw(kanaly('Return',prev));
const ustalone=stoi(q_sup,q_sup_prev)&&stoi(q_ext,q_ext_prev);
const kraniec=poz=>jest('PositionSupply')?(poz>=99||poz<=1):false;
const pomin=poz=>!ustalone||kraniec(poz);

const r=[];
if(jest('FlowSupply')&&S.length)
 r.push(['przeplyw nawiewu = suma (predkosc x przekroj kanalu) x 3600', q_sup_calc, p.FlowSupply, tol(q_sup_calc,p.FlowSupply,3)]);
if(jest('FlowReturn')&&R.length)
 r.push(['przeplyw wyciagu = suma (predkosc x przekroj kanalu) x 3600', q_ext_calc, p.FlowReturn, tol(q_ext_calc,p.FlowReturn,3)]);
r.push(['nastawa nawiewu wg rampy CO2 i trybu', sp_sup, q_sup, pomin(p.PositionSupply)||tol(sp_sup,q_sup,10,20)]);
r.push(['wyciag nadaza za nawiewem (nawiew - DIFF)', sp_ext, q_ext, pomin(p.PositionReturn)||tol(sp_ext,q_ext,10,20)]);
r.push(['roznica nawiew-wyciag = DIFF', p.Diff, q_sup-q_ext,
  pomin(p.PositionSupply)||pomin(p.PositionReturn)||tol(p.Diff,q_sup-q_ext,10,25)]);

// Lapie stara implementacje: (v1+v2) pomnozone przez JEDEN przekroj.
// Daje falszywy przeplyw wszedzie tam, gdzie oba kanaly nie sa identyczne.
function sumowanieBledne(ks, flow, opis){
 if(ks.length<2||!isFinite(flow)) return;
 const vsum=ks.reduce((s,c)=>s+c.k*c.v,0);
 const dobrze=przeplyw(ks);
 for(const c of ks){
  const zle=vsum*c.A*3600;
  if(tol(zle,flow,3)&&!tol(dobrze,flow,3))
   r.push([opis, dobrze, flow, false]);
 }
}
sumowanieBledne(S, p.FlowSupply, 'BLAD: nawiew sumuje predkosci i mnozy przez JEDEN przekroj');
sumowanieBledne(R, p.FlowReturn, 'BLAD: wyciag sumuje predkosci i mnozy przez JEDEN przekroj');

// Brakujace punkty zglaszamy wprost, zeby nie udawaly bledu regulacji.
const wymagane=['Mode','MinFlow','MaxFlow','CO2PropBand','CO2Setpoint','Diff','CO2'];
const brak=wymagane.filter(k=>!jest(k));
if(brak.length) r.push(['BRAK PUNKTOW (sprawdz mapowanie): '+brak.join(', '), 0, brak.length, false]);
if(!S.length) r.push(['BRAK kanalu nawiewnego (wymiary + predkosc)', 1, 0, false]);
if(!R.length) r.push(['BRAK kanalu wyciagowego (wymiary + predkosc)', 1, 0, false]);

// Kontrole konfiguracji
const zaDuzy=[...S,...R].some(c=>c.A>10);
if(zaDuzy) r.push(['wymiary kanalu w METRACH (wpisano mm?)', 1, 0, false]);
if(p.MinFlow>=p.MaxFlow) r.push(['MinFlow < MaxFlow', 1, 0, false]);
if(p.CO2PropBand<=0) r.push(['PropBand > 0', 1, 0, false]);
if(m===4) r.push(['UWAGA: tryb OFF (4) - regulacja wylaczona', 1, 0, false]);
return r;
